import {
  AlertTriangle,
  ArrowRight,
  Check,
  ChevronDown,
  ChevronRight,
  CircleAlert,
  Clipboard,
  ExternalLink,
  GitBranch,
  Layers3,
  Link2,
  LoaderCircle,
  Plus,
  RefreshCcw,
  ShieldCheck,
  Wallet,
  X,
} from 'lucide-react'
import type { CalldataEncodable } from 'genlayer-js/types'
import { BrowserRouter, Link, NavLink, Navigate, Route, Routes, useNavigate, useParams } from 'react-router-dom'
import {
  CONTRACT_ADDRESS,
  STUDIO_DEV_CHAIN_ID,
  STUDIO_DEV_CHAIN_HEX,
  friendlyError,
  getDashboardData,
  getDecision,
  getDecisionBundle,
  getDependantCount,
  getEventCount,
  getSource,
  getSourceCount,
  getWalletAddress,
  getWalletChainId,
  requestWallet,
  switchToStudioDevnet,
  waitForCount,
  waitForDecisionState,
  waitForDependency,
  waitForEventState,
  waitForSourceRevision,
  watchWallet,
  writeAndWait,
  type DashboardData,
  type DecisionBundle,
  type EventBundle,
  type SourceRecord,
} from './genlayer'
import { createContext, useCallback, useContext, useEffect, useMemo, useState, type CSSProperties, type FormEvent, type ReactNode } from 'react'

type WalletValue = { address: string | null; chainId: string | null; onTarget: boolean | null; hasProvider: boolean; providerName: string; error: string; revision: number; canWrite: boolean; writeBlockReason: string; connect: () => Promise<string>; switchNetwork: () => Promise<void>; disconnect: () => void }
type TxStage = 'idle' | 'awaiting' | 'submitted' | 'consensus' | 'confirming' | 'recorded' | 'rejected' | 'wrong-network' | 'unresolved' | 'execution-failed' | 'error'
type TxState = { stage: TxStage; title: string; detail: string; hash: string | null }
type WriteRequest = { functionName: string; args: CalldataEncodable[]; title: string; confirm: () => Promise<unknown> }
type TxValue = { tx: TxState; runWrite: (request: WriteRequest) => Promise<{ hash: string; confirmed: unknown }>; dismiss: () => void }
const WalletContext = createContext<WalletValue | null>(null)
const TxContext = createContext<TxValue | null>(null)
const DataContext = createContext<{ data: DashboardData | null; loading: boolean; error: string; refresh: () => Promise<void> } | null>(null)

function useWallet() { const value = useContext(WalletContext); if (!value) throw new Error('Wallet context is unavailable.'); return value }
function useTx() { const value = useContext(TxContext); if (!value) throw new Error('Transaction context is unavailable.'); return value }
function useData() { const value = useContext(DataContext); if (!value) throw new Error('Data context is unavailable.'); return value }
function sameAddress(left: string | null | undefined, right: string | null | undefined) { return Boolean(left && right && left.toLowerCase() === right.toLowerCase()) }
function shortAddress(value: string | null | undefined) { if (!value) return 'NO WALLET'; return value.length > 16 ? value.slice(0, 8) + '…' + value.slice(-6) : value }
function shortHash(value: string | null | undefined) { if (!value) return '—'; return value.length > 18 ? value.slice(0, 10) + '…' + value.slice(-8) : value }
function formatError(error: unknown) { return friendlyError(error) }
function statusTone(value: string) { if (value === 'CURRENT' || value === 'RECORDED' || value === 'ACTIVE') return 'current'; if (value === 'STALE' || value === 'ERROR' || value === 'rejected' || value === 'INACTIVE') return 'stale'; if (value === 'UNDETERMINED' || value === 'unresolved') return 'undetermined'; if (value === 'DRAFT' || value === 'submitted' || value === 'consensus' || value === 'confirming') return 'draft'; return 'neutral' }
function StatusTag({ value }: { value: string }) { return <span className={'status-tag ' + statusTone(value)}>{value}</span> }

function WalletProvider({ children }: { children: ReactNode }) {
  const [address, setAddress] = useState<string | null>(null); const [chainId, setChainId] = useState<string | null>(null); const [error, setError] = useState(''); const [manualDisconnect, setManualDisconnect] = useState(false); const [revision, setRevision] = useState(0); const hasProvider = typeof window !== 'undefined' && Boolean(window.ethereum)
  const bumpRevision = useCallback(() => setRevision((current) => current + 1), [])
  useEffect(() => { let active = true; Promise.all([getWalletAddress(), getWalletChainId()]).then(([nextAddress, nextChain]) => { if (!active || manualDisconnect) return; setAddress(nextAddress); setChainId(nextChain) }).catch((errorValue) => { if (active) setError(formatError(errorValue)) }); const unwatch = watchWallet((nextAddress) => { setManualDisconnect(false); setAddress(nextAddress); setError(''); bumpRevision() }, (nextChain) => { setChainId(nextChain); setError(''); bumpRevision() }, () => bumpRevision(), () => { setAddress(null); setChainId(null); setError('Wallet disconnected. Connect Rabby to write.'); bumpRevision() }); return () => { active = false; unwatch() } }, [manualDisconnect, bumpRevision])
  const connect = useCallback(async () => { try { const nextAddress = await requestWallet(); const nextChain = await getWalletChainId(); setManualDisconnect(false); setAddress(nextAddress); setChainId(nextChain); setError(''); bumpRevision(); return nextAddress } catch (errorValue) { setError(formatError(errorValue)); throw errorValue } }, [bumpRevision])
  const switchNetwork = useCallback(async () => { try { const nextChain = await switchToStudioDevnet(); setChainId(nextChain); setError(''); bumpRevision() } catch (errorValue) { setError(formatError(errorValue)); throw errorValue } }, [bumpRevision])
  const disconnect = useCallback(() => { setManualDisconnect(true); setAddress(null); setChainId(null); setError(''); bumpRevision() }, [bumpRevision])
  const onTarget = chainId ? chainId === STUDIO_DEV_CHAIN_HEX : null
  const canWrite = Boolean(address && onTarget === true)
  const writeBlockReason = !hasProvider ? 'Connect Rabby or another injected wallet before signing.' : !address ? 'Connect Rabby to enable Groundshift writes.' : !canWrite ? 'Switch the wallet to Studio-dev to enable Groundshift writes.' : ''
  return <WalletContext.Provider value={{ address, chainId, onTarget, hasProvider, providerName: hasProvider ? (window.ethereum?.isRabby ? 'Rabby' : 'Injected EVM') : 'No wallet', error, revision, canWrite, writeBlockReason, connect, switchNetwork, disconnect }}>{children}</WalletContext.Provider>
}

const initialTx: TxState = { stage: 'idle', title: '', detail: '', hash: null }
function classifyError(error: unknown): TxStage { const message = formatError(error); if (/reject|denied|4001|declined/i.test(message)) return 'rejected'; if (/wrong network|chain|studio-dev|studio devnet/i.test(message)) return 'wrong-network'; if (/consensus did not resolve|undetermined/i.test(message)) return 'unresolved'; if (/GenVM execution failed|rollback|execution/i.test(message)) return 'execution-failed'; return 'error' }
function TransactionProvider({ children }: { children: ReactNode }) { const wallet = useWallet(); const { refresh } = useData(); const [tx, setTx] = useState<TxState>(initialTx); const runWrite = useCallback(async (request: WriteRequest) => { try { const address = await getWalletAddress(); if (!address) throw new Error('Connect Rabby or another injected wallet before signing.'); const chainId = await getWalletChainId(); if (chainId !== STUDIO_DEV_CHAIN_HEX) throw new Error('Wrong network. Studio-dev chain ' + STUDIO_DEV_CHAIN_ID + ' is required before signing.'); setTx({ stage: 'awaiting', title: request.title, detail: 'Approve the transaction in ' + wallet.providerName + '.', hash: null }); const result = await writeAndWait(address, request.functionName, request.args, { onAwaitingWallet: () => setTx((current) => ({ ...current, stage: 'awaiting', detail: 'Approve the transaction in ' + wallet.providerName + '.' })), onSubmitted: (hash) => setTx((current) => ({ ...current, stage: 'submitted', detail: 'Submitted. Waiting for GenLayer consensus.', hash })), onConsensus: (hash) => setTx((current) => ({ ...current, stage: 'consensus', detail: 'Consensus accepted. Confirming authoritative contract state.', hash })) }); setTx((current) => ({ ...current, stage: 'confirming', detail: 'Reading the contract until the expected state is recorded.', hash: result.hash })); const confirmed = await request.confirm(); await refresh(); setTx({ stage: 'recorded', title: request.title, detail: 'Recorded in the authoritative contract state.', hash: result.hash }); return { hash: result.hash, confirmed } } catch (errorValue) { setTx((current) => ({ ...current, stage: classifyError(errorValue), detail: formatError(errorValue) })); throw errorValue } }, [wallet, refresh]); return <TxContext.Provider value={{ tx, runWrite, dismiss: () => setTx(initialTx) }}>{children}</TxContext.Provider> }
function DataProvider({ children }: { children: ReactNode }) { const wallet = useWallet(); const [data, setData] = useState<DashboardData | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const refresh = useCallback(async () => { setLoading(true); try { setData(await getDashboardData()); setError('') } catch (errorValue) { setError(formatError(errorValue)) } finally { setLoading(false) } }, []); useEffect(() => { void refresh() }, [refresh, wallet.revision]); return <DataContext.Provider value={{ data, loading, error, refresh }}>{children}</DataContext.Provider> }
function LoadingState({ label }: { label: string }) { return <div className="loading-state"><LoaderCircle className="spin" size={18} /><span>{label}</span></div> }
function ErrorState({ message, onRetry }: { message: string; onRetry: () => void }) { return <div className="error-state"><CircleAlert size={18} /><div><strong>Could not read Groundshift</strong><p>{message}</p></div><button className="button button-quiet" onClick={onRetry}>Retry</button></div> }
function DataGate({ children }: { children: (data: DashboardData) => ReactNode }) { const { data, loading, error, refresh } = useData(); if (loading && !data) return <LoadingState label="Reading live contract state…" />; if (error && !data) return <ErrorState message={error} onRetry={() => void refresh()} />; if (!data) return <ErrorState message="No contract state was returned." onRetry={() => void refresh()} />; return <>{children(data)}</> }
function EmptyState({ title, children, action }: { title: string; children: ReactNode; action?: ReactNode }) { return <div className="registry-empty"><Layers3 size={22} /><h2>{title}</h2><p>{children}</p>{action}</div> }
function RegistryHeader({ eyebrow, title, description, actions }: { eyebrow: string; title: string; description: string; actions?: ReactNode }) { return <div className="registry-header"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{actions && <div className="page-actions">{actions}</div>}</div> }
function Field({ label, hint, children }: { label: string; hint?: string; children: ReactNode }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label> }
function Fact({ label, value, mono = false }: { label: string; value: ReactNode; mono?: boolean }) { return <div className="fact"><span>{label}</span><strong className={mono ? 'mono' : ''}>{value}</strong></div> }
function InlineError({ message }: { message: string }) { return <div className="inline-error"><CircleAlert size={15} /><span>{message}</span></div> }
function CopyButton({ value }: { value: string }) { const [copied, setCopied] = useState(false); return <button className="copy-button" onClick={() => { void navigator.clipboard?.writeText(value).then(() => setCopied(true)); window.setTimeout(() => setCopied(false), 1400) }}><Clipboard size={14} /> {copied ? 'Copied' : 'Copy'}</button> }

function AppShell({ children }: { children: ReactNode }) {
  const wallet = useWallet(); const { tx, dismiss } = useTx(); const { data } = useData(); const [walletMenuOpen, setWalletMenuOpen] = useState(false); const staleCount = data?.decisions.filter((item) => item.decision.status === 'STALE').length ?? 0; const undeterminedCount = data?.decisions.filter((item) => item.decision.status === 'UNDETERMINED').length ?? 0; const currentCount = data?.decisions.filter((item) => item.decision.status === 'CURRENT').length ?? 0; const nav = [{ to: '/app', label: 'MAP', end: true }, { to: '/app/sources', label: 'SOURCES' }, { to: '/app/decisions', label: 'DECISIONS' }, { to: '/app/events', label: 'EVENTS' }, { to: '/app/repair', label: 'REPAIR' }]
  return <div className="app-shell"><header className="topbar"><Link className="wordmark" to="/"><span><strong>GROUND<br /><span className="shift">SHIFT</span></strong><small>DEPENDENCY ANALYSIS INSTRUMENT</small></span></Link><nav className="product-nav" aria-label="Product navigation">{nav.map(({ to, label, end }) => <NavLink key={to} to={to} end={end}>{label}</NavLink>)}</nav><div className="topbar-actions"><span className="network-readout"><span className="network-dot" data-live={wallet.onTarget === true} /> STUDIO-DEV</span><span className="contract-readout">{shortAddress(CONTRACT_ADDRESS)}</span>{wallet.address ? <div className="wallet-wrap"><button className="wallet-button" onClick={() => setWalletMenuOpen(!walletMenuOpen)}><span className="wallet-live" />{shortAddress(wallet.address)}<ChevronDown size={14} /></button>{walletMenuOpen && <div className="wallet-menu"><span className="menu-label">{wallet.providerName}</span><strong>{wallet.address}</strong><span className={wallet.onTarget ? 'menu-good' : 'menu-bad'}>{wallet.onTarget ? 'Studio-dev connected' : 'Wrong network'}</span>{!wallet.onTarget && <button onClick={() => void wallet.switchNetwork()}>Switch network</button>}<button onClick={wallet.disconnect}>Disconnect locally</button></div>}</div> : <button className="button button-dark connect-button" onClick={() => void wallet.connect()}><Wallet size={14} /> Connect</button>}</div></header><div className="state-line" aria-label="Live contract status"><span>SRC {data?.sourceCount ?? '—'}</span><span>DEC {data?.decisionCount ?? '—'}</span><span className="current">CURRENT {currentCount}</span><span className="stale">STALE {staleCount}</span><span className="undetermined">UNDET {undeterminedCount}</span><span className="state-authority"><span className="status-rail-dot" /> LIVE CONTRACT</span></div><main className="main-content">{wallet.address && wallet.onTarget === false && <div className="network-guard" role="alert"><div><strong>WRONG NETWORK</strong><span>Switch to Studio-dev to use Groundshift.</span></div><button className="button button-dark" onClick={() => void wallet.switchNetwork()}>SWITCH TO STUDIO-DEV</button></div>}{wallet.error && <div className="top-error"><CircleAlert size={15} /><span>{wallet.error}</span></div>}<div className="content-width">{children}</div></main>{tx.stage !== 'idle' && <TxBanner tx={tx} onDismiss={['recorded', 'error', 'rejected', 'wrong-network', 'unresolved', 'execution-failed'].includes(tx.stage) ? dismiss : undefined} />}</div>
}
function TxBanner({ tx, onDismiss }: { tx: TxState; onDismiss?: () => void }) { const busy = ['awaiting', 'submitted', 'consensus', 'confirming'].includes(tx.stage); return <div className={'tx-banner ' + statusTone(tx.stage)}>{busy ? <LoaderCircle size={16} className="spin" /> : tx.stage === 'recorded' ? <Check size={16} /> : <CircleAlert size={16} />}<div><strong>{tx.title || 'Transaction'}</strong><span>{tx.detail}</span>{tx.hash && <code>{shortHash(tx.hash)}</code>}</div>{onDismiss && <button className="icon-button" aria-label="Dismiss transaction status" onClick={onDismiss}><X size={16} /></button>}</div> }

type StratumItem = { key: string; label: string; title: string; status: string; revision: number; kind: 'SOURCE' | 'DECISION'; offset: number; detail: string; source?: SourceRecord; bundle?: DecisionBundle }
function decisionDepth(bundle: DecisionBundle, byId: Map<number, DecisionBundle>, seen = new Set<number>()): number { if (seen.has(bundle.decision.id)) return 0; const parents = bundle.dependencies.filter((item) => item.dependency_type === 'DECISION').map((item) => byId.get(item.parent_id)).filter(Boolean) as DecisionBundle[]; if (!parents.length) return 1; return Math.max(...parents.map((parent) => decisionDepth(parent, byId, new Set(seen).add(bundle.decision.id)))) + 1 }
function makeStrata(data: DashboardData): StratumItem[] { const byId = new Map(data.decisions.map((item) => [item.decision.id, item])); const sources = data.sources.map((source) => ({ key: 'S' + source.id, label: 'S·' + source.id.toString().padStart(2, '0'), title: source.title || 'POLICY SOURCE', status: source.active ? 'CURRENT' : 'STALE', revision: source.revision, kind: 'SOURCE' as const, offset: 0, detail: source.canonical_url, source })); const decisions = [...data.decisions].sort((a, b) => decisionDepth(a, byId) - decisionDepth(b, byId) || a.decision.id - b.decision.id); const rows = decisions.map((bundle) => ({ key: 'D' + bundle.decision.id, label: 'D·' + bundle.decision.id.toString().padStart(2, '0'), title: bundle.decision.question || 'UNNAMED DECISION', status: bundle.decision.status, revision: bundle.decision.revision, kind: 'DECISION' as const, offset: bundle.decision.status === 'STALE' ? Math.min(3, bundle.decision.stale_depth || 1) * 20 : 0, detail: bundle.dependencies.length + ' declared basis link' + (bundle.dependencies.length === 1 ? '' : 's'), bundle })); return [...sources, ...rows] }
function Stratum({ item, expanded, onToggle, children }: { item: StratumItem; expanded: boolean; onToggle: () => void; children: ReactNode }) { const style = { '--offset': item.offset } as CSSProperties; return <article className={'stratum ' + statusTone(item.status) + (expanded ? ' expanded' : '')} style={style} data-offset={item.offset} data-kind={item.kind}><div className="stratum-row" role="button" tabIndex={0} onClick={onToggle} onKeyDown={(event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); onToggle() } }}><span className="stratum-marker" aria-hidden="true" /><span className="stratum-code">{item.label}</span><span className="stratum-title"><strong>{item.title}</strong><small>{item.kind} · REV {item.revision.toString().padStart(2, '0')} · {item.detail}</small></span><span className={'stratum-state ' + statusTone(item.status)}>{item.status}</span><span className="stratum-rule" aria-hidden="true" /><ChevronDown className="stratum-chevron" size={16} /></div>{expanded && <div className="stratum-expansion">{children}</div>}</article> }
function FaultScar({ label = 'FAULT 01' }: { label?: string }) { return <span className="fault-scar" aria-label={label}><i /><i /><i /><em>{label}</em></span> }
function BasisStitch({ label }: { label: string }) { return <div className="basis-stitch"><span className="basis-stitch-line" /><span>{label}</span><span className="basis-stitch-line" /></div> }
function RevisionTrack({ source }: { source: SourceRecord }) { const revisions = Array.from({ length: Math.max(7, source.revision) }, (_, index) => index + 1); return <div className="revision-track"><span className="track-label">REVISION HISTORY</span><div>{revisions.map((revision) => <span key={revision} className={revision === source.revision ? 'active' : revision < source.revision ? 'past' : ''}>{revision.toString().padStart(2, '0')}{revision === source.revision ? ' ●' : ' ━━━'}</span>)}</div></div> }
function BasisAlignment({ bundle, data }: { bundle: DecisionBundle; data: DashboardData }) { const basis = bundle.dependencies.map((dependency) => { const current = dependency.dependency_type === 'SOURCE' ? data.sources.find((source) => source.id === dependency.parent_id)?.revision : data.decisions.find((item) => item.decision.id === dependency.parent_id)?.decision.revision; const aligned = dependency.dependency_type === 'SOURCE' ? current === dependency.parent_revision_at_evaluation : current === dependency.parent_revision_at_evaluation && data.decisions.find((item) => item.decision.id === dependency.parent_id)?.decision.status === 'CURRENT'; return <div key={dependency.dependency_index} className={'basis-alignment ' + (aligned ? 'aligned' : 'misaligned')}><span>{dependency.dependency_type[0]}·{dependency.parent_id.toString().padStart(2, '0')}</span><span>evaluated r{dependency.parent_revision_at_evaluation.toString().padStart(2, '0')}</span><span className="basis-connector" /><span>{aligned ? 'CURRENT BASIS' : 'MISALIGNED / REPAIR'}</span></div> }); return <div className="basis-alignment-list">{basis.length ? basis : <span className="quiet-copy">No basis attached yet.</span>}</div> }
function SourceExpansion({ source }: { source: SourceRecord }) { const [dependants, setDependants] = useState<number | null>(null); useEffect(() => { void getDependantCount('SOURCE', source.id).then(setDependants).catch(() => setDependants(0)) }, [source.id]); return <div className="expansion-grid"><div><span className="eyebrow">CANONICAL SOURCE</span><a className="source-link" href={source.canonical_url} target="_blank" rel="noreferrer">{source.canonical_url} <ExternalLink size={12} /></a></div><div className="expansion-facts"><Fact label="FINGERPRINT" value={source.fingerprint} mono /><Fact label="OWNER" value={shortAddress(source.owner)} mono /><Fact label="DEPENDANTS" value={dependants === null ? '—' : dependants} /></div><RevisionTrack source={source} /><Link className="text-link" to={'/app/sources/' + source.id}>Open source record <ArrowRight size={13} /></Link></div> }
function DecisionExpansion({ bundle, data }: { bundle: DecisionBundle; data: DashboardData }) { const decision = bundle.decision; return <div className="expansion-grid"><BasisAlignment bundle={bundle} data={data} /><div className="expansion-facts"><Fact label="OUTCOME" value={decision.outcome || 'DRAFT / NO OUTCOME'} /><Fact label="REVISION" value={'r' + decision.revision} /><Fact label="STALE DEPTH" value={decision.stale_depth || 0} /><Fact label="OWNER" value={shortAddress(decision.owner)} mono /></div>{decision.stale_origin_type && <div className="provenance-inline"><AlertTriangle size={14} /> STALE PROVENANCE: {decision.stale_origin_type} #{decision.stale_origin_id} · event #{decision.stale_event_id}</div>}<Link className="text-link" to={'/app/decisions/' + decision.id}>Open decision record <ArrowRight size={13} /></Link></div> }
function StrataWorkspace({ data, event }: { data: DashboardData; event?: EventBundle }) { const [expanded, setExpanded] = useState<string | null>(null); const items = useMemo(() => makeStrata(data), [data]); if (!items.length) return <section className="strata-field empty-field"><div className="origin-plus">+</div><div className="empty-rule" /><div className="strata-empty-copy"><strong>NO STRATA YET</strong><span>Groundshift begins upstream.</span><Link className="text-link strong-link" to="/app/sources/new">REGISTER FIRST SOURCE <ArrowRight size={13} /></Link><small>Then create a decision and attach its basis.</small></div><div className="guide-strata" aria-label="Structure guide"><div><span>STRUCTURE GUIDE</span><strong>SOURCE</strong></div><div><span>STRUCTURE GUIDE</span><strong>DECISION</strong></div></div></section>; return <section className="strata-field"><div className="field-meta"><span>LIVE STRATA / {items.length} RECORDS</span><span>{event ? 'HISTORICAL EVENT #' + event.event.id : 'SELECT A STRATUM TO EXPAND INLINE'}</span></div><div className="strata-stack">{items.map((item, index) => <div className="stratum-lane" key={item.key}><Stratum item={item} expanded={expanded === item.key} onToggle={() => setExpanded(expanded === item.key ? null : item.key)}>{item.kind === 'SOURCE' && item.source ? <SourceExpansion source={item.source} /> : item.bundle ? <DecisionExpansion bundle={item.bundle} data={data} /> : null}</Stratum>{item.kind === 'DECISION' && item.bundle && item.bundle.dependencies[0] && <BasisStitch label={'BASIS / ' + item.bundle.dependencies[0].dependency_type + '·' + item.bundle.dependencies[0].parent_id + ' / r' + item.bundle.dependencies[0].parent_revision_at_evaluation} />}{item.status === 'STALE' && <FaultScar label="FAULT 01" />}{index < items.length - 1 && item.status !== 'STALE' && <div className="strata-continuation" />}</div>)}</div></section> }
function EventPulse({ data }: { data: DashboardData }) { return <section className="event-pulse"><div><span className="eyebrow">EVENT STREAM</span><strong>{data.eventCount} EVENTS</strong></div>{data.events.length ? <div className="event-marks">{data.events.slice(0, 10).map((bundle) => <Link key={bundle.event.id} to={'/app/events/' + bundle.event.id} title={'Event #' + bundle.event.id}><i className={bundle.event.completed ? 'complete' : 'pending'} /></Link>)}</div> : <span className="quiet-copy">NO PROPAGATION EVENTS</span>}<Link className="text-link" to="/app/events">Open history <ArrowRight size={13} /></Link></section> }
function ControlRoom() { return <DataGate>{(data) => <main className="map-page"><StrataWorkspace data={data} /><div className="map-foot"><span>AUTHORITY / DEPLOYED CONTRACT STATE</span><span className="mono">{data.eventCount} EVENTS · {shortAddress(CONTRACT_ADDRESS)} · CHAIN {STUDIO_DEV_CHAIN_ID}</span></div><EventPulse data={data} /></main>}</DataGate> }
function isReady(bundle: DecisionBundle, data: DashboardData) { return bundle.dependencies.every((dependency) => { if (dependency.dependency_type === 'SOURCE') { const source = data.sources.find((item) => item.id === dependency.parent_id); return Boolean(source && source.active && source.revision === dependency.parent_revision_at_evaluation) } const parent = data.decisions.find((item) => item.decision.id === dependency.parent_id); return Boolean(parent && parent.decision.status === 'CURRENT') }) }
function blockReason(bundle: DecisionBundle, data: DashboardData) { const blocked = bundle.dependencies.find((dependency) => { if (dependency.dependency_type === 'SOURCE') { const source = data.sources.find((item) => item.id === dependency.parent_id); return !source || !source.active || source.revision !== dependency.parent_revision_at_evaluation } const parent = data.decisions.find((item) => item.decision.id === dependency.parent_id); return !parent || parent.decision.status !== 'CURRENT' }); if (!blocked) return 'Waiting for declared evidence.'; return blocked.dependency_type + ' #' + blocked.parent_id + ' is ' + (blocked.dependency_type === 'DECISION' ? (data.decisions.find((item) => item.decision.id === blocked.parent_id)?.decision.status || 'MISSING') : 'REVISION DRIFT') }
function EventRow({ bundle }: { bundle: EventBundle }) { const event = bundle.event; return <Link className="event-row" to={'/app/events/' + event.id}><span className="event-index">#{event.id}</span><span><strong>{event.origin_type} #{event.origin_id} / REV {event.origin_revision}</strong><small>{event.affected_decision_count} decisions affected</small></span><StatusTag value={event.completed ? 'COMPLETED' : 'PENDING'} /><ChevronRight size={15} /></Link> }
function EventRuler({ data }: { data: DashboardData }) { return <section className="event-instrument"><div className="event-ruler-label"><span>PAST</span><span>NOW</span></div><div className="event-ruler"><span className="event-ruler-origin">{data.events.length ? '●' : '○'}</span><span className="event-ruler-line" /><span className="event-ruler-axis">┼</span></div>{data.events.length ? <div className="event-history-rows">{data.events.map((bundle) => <EventRow key={bundle.event.id} bundle={bundle} />)}</div> : <div className="event-empty"><strong>NO FAULT EVENTS</strong><span>No source revision has displaced a dependency basis yet.</span></div>}</section> }

function SourcesPage() { return <DataGate>{(data) => <><div className="route-instrument-title">SOURCE STRATA</div>{data.sources.length ? <section className="registry-list source-strata-list"><div className="registry-list-head"><span>{data.sourceCount} REGISTERED SOURCES</span><span>OWNER · REVISION · DEPENDANTS</span></div>{data.sources.map((source) => <SourceTableRow key={source.id} source={source} />)}</section> : <section className="instrument-empty"><strong>NO SOURCE STRATA</strong><span className="instrument-rule" /><Link className="text-link strong-link" to="/app/sources/new">REGISTER SOURCE <ArrowRight size={13} /></Link></section>}</>}</DataGate> }
function SourceTableRow({ source }: { source: SourceRecord }) { const [dependants, setDependants] = useState<number | null>(null); useEffect(() => { void getDependantCount('SOURCE', source.id).then(setDependants).catch(() => setDependants(0)) }, [source.id]); return <Link className="registry-row" to={'/app/sources/' + source.id}><span><strong>S{source.id}</strong><small>{source.title}</small></span><span className="truncate mono">{source.canonical_url}</span><span className="mono">r{source.revision}</span><span className="mono">{dependants === null ? '—' : dependants}</span><StatusTag value={source.active ? 'ACTIVE' : 'INACTIVE'} /><ChevronRight size={15} /></Link> }
function CreateSourcePage() { const { data } = useData(); const { runWrite } = useTx(); const navigate = useNavigate(); const [form, setForm] = useState({ title: '', url: '', fingerprint: '' }); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const submit = async (event: FormEvent) => { event.preventDefault(); if (!data) return; setError(''); setBusy(true); try { await runWrite({ functionName: 'register_source', args: [form.title.trim(), form.url.trim(), form.fingerprint.trim()] as unknown as CalldataEncodable[], title: 'Register source', confirm: async () => { const count = await waitForCount(getSourceCount, data.sourceCount + 1, 'source registry'); await navigate('/app/sources/' + count); return count } }) } catch (errorValue) { setError(formatError(errorValue)) } finally { setBusy(false) } }; return <><RegistryHeader eyebrow="SOURCES / NEW RECORD" title="Register a source." description="Give the decision system a canonical HTTPS source and a short fingerprint." actions={<Link className="button button-quiet" to="/app/sources">Back to sources</Link>} /><form className="form-surface" onSubmit={submit}><Field label="Title"><input required maxLength={120} value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} placeholder="Vendor security policy" /></Field><Field label="Canonical HTTPS URL"><input required type="url" maxLength={1200} value={form.url} onChange={(e) => setForm({ ...form, url: e.target.value })} placeholder="https://example.com/policy" /></Field><Field label="Fingerprint" hint="Changing this string advances the source revision."><input required maxLength={256} value={form.fingerprint} onChange={(e) => setForm({ ...form, fingerprint: e.target.value })} placeholder="sha256:…" /></Field>{error && <InlineError message={error} />}<div className="form-footer"><span>Writes are signed by the connected wallet.</span><button className="button button-dark" disabled={busy}>{busy ? <LoaderCircle size={15} className="spin" /> : <Plus size={15} />} Register source</button></div></form></> }
function SourceDossier() { const id = Number(useParams().id); return <DataGate>{(data) => { const source = data.sources.find((item) => item.id === id); return source ? <SourceDossierBody data={data} source={source} /> : <NotFound label="Source" back="/app/sources" /> }}</DataGate> }
function SourceDossierBody({ data, source }: { data: DashboardData; source: SourceRecord }) { const wallet = useWallet(); const { refresh } = useData(); const { runWrite } = useTx(); const [fingerprint, setFingerprint] = useState(source.fingerprint); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const owner = sameAddress(wallet.address, source.owner); const revise = async (event: FormEvent) => { event.preventDefault(); setError(''); setBusy(true); try { await runWrite({ functionName: 'revise_source', args: [source.id, fingerprint.trim()] as unknown as CalldataEncodable[], title: 'Revise source S' + source.id, confirm: async () => { await waitForSourceRevision(source.id, source.revision + 1); await waitForCount(getEventCount, data.eventCount + 1, 'propagation event'); await refresh(); return getSource(source.id) } }) } catch (errorValue) { setError(formatError(errorValue)) } finally { setBusy(false) } }; return <><RegistryHeader eyebrow="SOURCE DOSSIER / S" title={'Source #' + source.id} description="A source revision is an operational boundary. Follow its dependants and inspect historical breaks." actions={<Link className="button button-quiet" to="/app/sources">← Registry</Link>} /><section className="record-surface"><div className="record-heading"><span className="record-code source-code">S{source.id}</span><div><span className="eyebrow">CANONICAL SOURCE</span><h2>{source.title}</h2></div><StatusTag value={source.active ? 'ACTIVE' : 'INACTIVE'} /></div><div className="fact-grid"><Fact label="REVISION" value={'r' + source.revision} /><Fact label="OWNER" value={shortAddress(source.owner)} mono /><Fact label="FINGERPRINT" value={source.fingerprint} mono /></div><a className="source-link" href={source.canonical_url} target="_blank" rel="noreferrer">{source.canonical_url} <ExternalLink size={13} /></a></section><section className="action-surface"><span className="eyebrow">REVISION DRIFT</span><p>Changing the fingerprint can invalidate every downstream decision that evaluated the previous revision.</p>{owner ? <form onSubmit={revise}><Field label="NEW FINGERPRINT"><input required maxLength={256} value={fingerprint} onChange={(e) => setFingerprint(e.target.value)} /></Field>{error && <InlineError message={error} />}<button className="button button-dark" disabled={busy || fingerprint.trim() === source.fingerprint}>{busy ? <LoaderCircle size={15} className="spin" /> : <RefreshCcw size={15} />} Revise source</button></form> : <div className="read-only"><ShieldCheck size={15} /> Owner controls are limited to the source owner.</div>}</section></> }

function DecisionsPage() { return <DataGate>{(data) => <><div className="route-instrument-title">BASIS ALIGNMENT</div>{data.decisions.length ? <section className="registry-list"><div className="registry-list-head"><span>{data.decisionCount} DECISIONS REGISTERED</span><span>STATUS · REVISION · BASIS</span></div>{data.decisions.map((bundle) => <Link className="registry-row" key={bundle.decision.id} to={'/app/decisions/' + bundle.decision.id}><span><strong>D{bundle.decision.id}</strong><small>{bundle.decision.question}</small></span><StatusTag value={bundle.decision.status} /><span className="mono">r{bundle.decision.revision}</span><span className="mono">{bundle.dependencies.length} linked</span><span className="mono truncate">{shortAddress(bundle.decision.owner)}</span><ChevronRight size={15} /></Link>)}</section> : <section className="alignment-empty"><div><span>EVALUATED BASIS</span><i /></div><div><span>CURRENT BASIS</span><i /></div><strong>NO DECISIONS YET</strong><Link className="text-link strong-link" to="/app/decisions/new">CREATE DECISION <ArrowRight size={13} /></Link></section>}</>}</DataGate> }
function CreateDecisionPage() { const { data } = useData(); const { runWrite } = useTx(); const navigate = useNavigate(); const [question, setQuestion] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const submit = async (event: FormEvent) => { event.preventDefault(); if (!data) return; setError(''); setBusy(true); try { await runWrite({ functionName: 'create_decision', args: [question.trim()] as unknown as CalldataEncodable[], title: 'Create draft decision', confirm: async () => { const nextId = await waitForCount(async () => (await import('./genlayer')).getDecisionCount(), data.decisionCount + 1, 'decision registry'); await navigate('/app/decisions/' + nextId); return nextId } }) } catch (errorValue) { setError(formatError(errorValue)) } finally { setBusy(false) } }; return <><RegistryHeader eyebrow="DECISIONS / NEW DRAFT" title="Put a question under watch." description="Create a draft, attach its declared basis, then finalize the outcome." actions={<Link className="button button-quiet" to="/app/decisions">Back to decisions</Link>} /><form className="form-surface" onSubmit={submit}><Field label="Decision question"><textarea required maxLength={1000} rows={5} value={question} onChange={(e) => setQuestion(e.target.value)} placeholder="Should Vendor A receive production access?" /></Field>{error && <InlineError message={error} />}<div className="form-footer"><span>Creates status DRAFT / revision 0.</span><button className="button button-dark" disabled={busy}>{busy ? <LoaderCircle size={15} className="spin" /> : <Plus size={15} />} Create draft</button></div></form></> }
function DecisionDossier() { const id = Number(useParams().id); return <DataGate>{(data) => { const bundle = data.decisions.find((item) => item.decision.id === id); return bundle ? <DecisionDossierBody data={data} bundle={bundle} /> : <NotFound label="Decision" back="/app/decisions" /> }}</DataGate> }
function DecisionDossierBody({ data, bundle }: { data: DashboardData; bundle: DecisionBundle }) { const decision = bundle.decision; const wallet = useWallet(); const { runWrite } = useTx(); const { refresh } = useData(); const owner = sameAddress(wallet.address, decision.owner); const ready = isReady(bundle, data); const [sourceId, setSourceId] = useState(''); const [parentId, setParentId] = useState(''); const [outcome, setOutcome] = useState(''); const [reasoning, setReasoning] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(''); const unusedSources = data.sources.filter((source) => !bundle.dependencies.some((dependency) => dependency.dependency_type === 'SOURCE' && dependency.parent_id === source.id)); const unusedParents = data.decisions.filter((parent) => parent.decision.id < decision.id && parent.decision.status === 'CURRENT' && !bundle.dependencies.some((dependency) => dependency.dependency_type === 'DECISION' && dependency.parent_id === parent.decision.id)); const addDependency = async (type: 'SOURCE' | 'DECISION') => { const selected = Number(type === 'SOURCE' ? sourceId : parentId); if (!selected) return; setError(''); setBusy(type.toLowerCase()); try { await runWrite({ functionName: type === 'SOURCE' ? 'add_source_dependency' : 'add_decision_dependency', args: [decision.id, selected] as unknown as CalldataEncodable[], title: 'Add ' + type.toLowerCase() + ' dependency', confirm: async () => { await waitForDependency(decision.id, bundle.dependencies.length); await refresh(); return getDecisionBundle(decision.id) } }); if (type === 'SOURCE') setSourceId(''); else setParentId('') } catch (errorValue) { setError(formatError(errorValue)) } finally { setBusy('') } }; const finalize = async (event: FormEvent) => { event.preventDefault(); setError(''); setBusy('finalize'); try { await runWrite({ functionName: 'finalize_decision', args: [decision.id, outcome.trim(), reasoning.trim()] as unknown as CalldataEncodable[], title: 'Finalize decision D' + decision.id, confirm: async () => { await waitForDecisionState(decision.id, ['CURRENT'], decision.revision + 1); await refresh(); return getDecision(decision.id) } }) } catch (errorValue) { setError(formatError(errorValue)) } finally { setBusy('') } }; const reevaluate = async () => { setError(''); setBusy('reevaluate'); try { await runWrite({ functionName: 'reevaluate_decision', args: [decision.id] as unknown as CalldataEncodable[], title: 'Reevaluate decision D' + decision.id, confirm: async () => { const result = await waitForDecisionState(decision.id, ['CURRENT', 'UNDETERMINED']); await refresh(); return result } }) } catch (errorValue) { setError(formatError(errorValue)) } finally { setBusy('') } }; return <><RegistryHeader eyebrow="DECISION DOSSIER / D" title={'Decision #' + decision.id} description={decision.question} actions={<><Link className="button button-quiet" to="/app/decisions">← Registry</Link><CopyButton value={CONTRACT_ADDRESS + ' / D' + decision.id} /></>} /><section className="record-surface decision-record"><div className="record-heading"><span className={'record-code ' + statusTone(decision.status)}>D{decision.id}</span><div><span className="eyebrow">QUESTION</span><h2>{decision.question}</h2></div><StatusTag value={decision.status} /></div><div className="fact-grid"><Fact label="REVISION" value={'r' + decision.revision} /><Fact label="OWNER" value={shortAddress(decision.owner)} mono /><Fact label="OUTCOME" value={decision.outcome || 'NO OUTCOME RECORDED'} /></div></section><section className="basis-surface"><div className="section-line"><span className="eyebrow">DEPENDENCY BASIS</span><span>{bundle.dependencies.length} / 8 SLOTS USED</span></div><BasisAlignment bundle={bundle} data={data} /></section>{decision.status === 'DRAFT' && owner && <section className="action-surface"><div className="section-line"><span className="eyebrow">ADD DEPENDENCY</span><span>MAX 8</span></div><div className="builder-grid"><div><Field label="SOURCE"><select value={sourceId} onChange={(e) => setSourceId(e.target.value)}><option value="">Select a source…</option>{unusedSources.map((source) => <option key={source.id} value={source.id}>S{source.id} · {source.title}</option>)}</select></Field><button className="button button-quiet" disabled={!sourceId || busy !== ''} onClick={() => void addDependency('SOURCE')}>{busy === 'source' ? <LoaderCircle size={14} className="spin" /> : <Link2 size={14} />} Attach source</button></div><div><Field label="CURRENT DECISION PARENT"><select value={parentId} onChange={(e) => setParentId(e.target.value)}><option value="">Select a current parent…</option>{unusedParents.map((parent) => <option key={parent.decision.id} value={parent.decision.id}>D{parent.decision.id} · {parent.decision.question}</option>)}</select></Field><button className="button button-quiet" disabled={!parentId || busy !== ''} onClick={() => void addDependency('DECISION')}>{busy === 'decision' ? <LoaderCircle size={14} className="spin" /> : <Link2 size={14} />} Attach decision</button></div></div></section>}{decision.status === 'DRAFT' && owner && bundle.dependencies.length > 0 && <form className="action-surface" onSubmit={finalize}><div className="section-line"><span className="eyebrow">FINALIZE DECISION</span><span>CONTRACT CHECKS BASIS CURRENCY</span></div><Field label="Outcome"><input required maxLength={2000} value={outcome} onChange={(e) => setOutcome(e.target.value)} placeholder="ELIGIBLE" /></Field><Field label="Reasoning"><textarea required maxLength={4000} rows={4} value={reasoning} onChange={(e) => setReasoning(e.target.value)} placeholder="The declared evidence supports…" /></Field>{error && <InlineError message={error} />}<button className="button button-dark" disabled={busy !== ''}>{busy === 'finalize' ? <LoaderCircle size={15} className="spin" /> : <Check size={15} />} Finalize</button></form>}{(decision.status === 'STALE' || decision.status === 'UNDETERMINED') && <section className="action-surface"><span className="eyebrow">REPAIR STATUS</span><h3>{ready ? 'READY FOR REPAIR' : 'BLOCKED BY BASIS'}</h3><p>{ready ? (decision.status === 'UNDETERMINED' ? 'Retry when evidence or upstream state changes.' : 'All declared dependencies are current.') : blockReason(bundle, data)}</p>{owner && ready && <button className="button button-dark" disabled={busy !== ''} onClick={() => void reevaluate()}>{busy === 'reevaluate' ? <LoaderCircle size={15} className="spin" /> : <RefreshCcw size={15} />} Reevaluate decision</button>}</section>}{error && decision.status !== 'DRAFT' && <InlineError message={error} />}</> }
function EventsPage() { return <DataGate>{(data) => <><div className="route-instrument-title">FAULT HISTORY</div><EventRuler data={data} /></>}</DataGate> }
function EventDossier() { const id = Number(useParams().id); return <DataGate>{(data) => { const bundle = data.events.find((item) => item.event.id === id); return bundle ? <EventDossierBody data={data} bundle={bundle} /> : <NotFound label="Propagation event" back="/app/events" /> }}</DataGate> }
function EventDossierBody({ data, bundle }: { data: DashboardData; bundle: EventBundle }) { const { runWrite } = useTx(); const { refresh } = useData(); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const event = bundle.event; const affected = bundle.affected.map((item) => data.decisions.find((decision) => decision.decision.id === item.decision_id)).filter(Boolean) as DecisionBundle[]; const continuePropagation = async () => { setError(''); setBusy(true); try { await runWrite({ functionName: 'continue_propagation', args: [event.id] as unknown as CalldataEncodable[], title: 'Continue propagation event #' + event.id, confirm: async () => { const result = await waitForEventState(event.id); await refresh(); return result } }) } catch (errorValue) { setError(formatError(errorValue)) } finally { setBusy(false) } }; return <><RegistryHeader eyebrow="EVENT DOSSIER / BLAST RADIUS" title={'Event #' + event.id} description="Historical strata affected by a basis change." actions={<Link className="button button-quiet" to="/app/events">← Event history</Link>} /><section className="record-surface event-record"><div><span className="eyebrow">ORIGIN</span><h2>{event.origin_type} #{event.origin_id}</h2><span className="mono">REV {event.origin_revision}</span></div><div className="fact-grid"><Fact label="AFFECTED" value={event.affected_decision_count} /><Fact label="STATUS" value={event.completed ? 'COMPLETED' : 'PENDING'} /><Fact label="REPAIRED" value={affected.filter((item) => item.decision.status === 'CURRENT').length} /></div></section><section className="history-surface"><div className="section-line"><span className="eyebrow">HISTORICAL STRATA / EVENT #{event.id}</span><span>{event.completed ? 'FAULT CLOSED' : 'FAULT OPEN'}</span></div><StrataWorkspace data={data} event={bundle} /></section>{!event.completed && <button className="button button-dark" disabled={busy} onClick={() => void continuePropagation()}>{busy ? <LoaderCircle size={15} className="spin" /> : <ArrowRight size={15} />} Continue propagation</button>}{error && <InlineError message={error} />}</> }
function StabilizationRow({ order, bundle, blockedBy }: { order: number; bundle: DecisionBundle; blockedBy?: string }) { const wallet = useWallet(); const { runWrite } = useTx(); const { refresh } = useData(); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const owner = sameAddress(wallet.address, bundle.decision.owner); const ready = !blockedBy; const repair = async () => { setError(''); setBusy(true); try { await runWrite({ functionName: 'reevaluate_decision', args: [bundle.decision.id] as unknown as CalldataEncodable[], title: 'Reevaluate D' + bundle.decision.id, confirm: async () => { const result = await waitForDecisionState(bundle.decision.id, ['CURRENT', 'UNDETERMINED']); await refresh(); return result } }) } catch (errorValue) { setError(formatError(errorValue)) } finally { setBusy(false) } }; return <div className={'stabilization-row ' + (ready ? 'ready' : 'blocked')}><span className="repair-order">0{order}</span><span className="stabilization-line" /><span className="stabilization-copy"><strong>D{bundle.decision.id} / {bundle.decision.question}</strong><small>{blockedBy || 'Basis aligned · reevaluation may proceed.'}</small></span><StatusTag value={bundle.decision.status} />{ready && owner ? <button className="button button-dark" disabled={busy} onClick={() => void repair()}>{busy ? <LoaderCircle size={14} className="spin" /> : <RefreshCcw size={14} />} Repair</button> : <span className="repair-state">{ready ? 'OWNER ONLY' : 'BLOCKED'}</span>}{error && <small className="row-error">{error}</small>}</div> }
function RepairPage() { return <DataGate>{(data) => { const stale = data.decisions.filter((item) => item.decision.status === 'STALE'); const ready = stale.filter((item) => isReady(item, data)); const blocked = stale.filter((item) => !isReady(item, data)); const unresolved = data.decisions.filter((item) => item.decision.status === 'UNDETERMINED'); return <><div className="route-instrument-title">STABILIZATION</div>{stale.length || unresolved.length ? <section className="stabilization-layout"><div className="stabilization-head"><span>REPAIR ORDER</span><span>{ready.length} READY</span></div>{ready.map((bundle, index) => <StabilizationRow key={bundle.decision.id} order={index + 1} bundle={bundle} />)}{blocked.map((bundle, index) => <StabilizationRow key={bundle.decision.id} order={ready.length + index + 1} bundle={bundle} blockedBy={blockReason(bundle, data)} />)}{unresolved.length > 0 && <div className="stabilization-note"><span className="undetermined">UNDETERMINED</span><span>{unresolved.length} decisions need a supported reevaluation after the basis is safe.</span></div>}</section> : <section className="stabilization-empty"><div /><div /><div /><strong>NO STALE STRATA</strong><span>The dependency field is stable.</span></section>}</> }}</DataGate> }
function GraphPage() { return <DataGate>{(data) => <><div className="route-instrument-title">LIVE STRATA MAP</div><StrataWorkspace data={data} /></>}</DataGate> }
function NotFound({ label, back }: { label: string; back: string }) { return <EmptyState title={label + ' not found.'}><Link className="button button-quiet" to={back}>Return to registry</Link></EmptyState> }

function LandingStrataDemo() { return <section className="landing-reference-board" aria-label="Illustrative Groundshift system demonstration"><div className="board-instrument-top"><span>GROUND / SHIFT</span><span>SYSTEM / EXAMPLE TRACE</span><span>STUDIO-DEV</span></div><div className="board-model-note">PROPAGATION / EXAMPLE TRACE · ILLUSTRATIVE MODEL</div><div className="board-vertical">DEPENDENCY SHIFT</div><div className="board-strata"><div className="board-layer board-source"><span className="board-code">S·01</span><span className="board-layer-name"><strong>POLICY SOURCE</strong><small>REV 04 → 05</small></span><b className="board-state">SHIFTED BASIS</b></div><div className="board-fault-note"><FaultScar label="FAULT 01 · S·01 04 → 05" /></div><div className="board-layer board-stale board-d1"><span className="board-code">D·01</span><span className="board-layer-name"><strong>ELIGIBILITY</strong><small>DEPENDENCY BASIS MISALIGNED</small></span><b className="board-state">STALE</b></div><div className="board-layer board-stale board-d2"><span className="board-code">D·02</span><span className="board-layer-name"><strong>ACCESS</strong><small>DOWNSTREAM DEPENDENCY</small></span><b className="board-state">STALE</b></div><div className="board-layer board-stale board-d3"><span className="board-code">D·03</span><span className="board-layer-name"><strong>RELEASE</strong><small>DOWNSTREAM DEPENDENCY</small></span><b className="board-state">STALE</b></div><div className="board-layer board-current board-s2"><span className="board-code">S·02</span><span className="board-layer-name"><strong>INDEPENDENT SOURCE</strong><small>REV 02 / UNTOUCHED BASIS</small></span><b className="board-state">CURRENT</b></div><div className="board-layer board-current board-d4"><span className="board-code">D·04</span><span className="board-layer-name"><strong>INDEPENDENT DECISION</strong><small>BASIS ALIGNED</small></span><b className="board-state">CURRENT</b></div></div><div className="board-instrument-bottom"><span>FAULT 01</span><span>3 STALE</span><span>1 UNAFFECTED</span></div><aside className="board-diagnostic"><span className="eyebrow">FAULT / 01</span><div className="diagnostic-facts"><span>ORIGIN <b>S·01</b></span><span>REVISION <b>04 → 05</b></span><span>AFFECTED <b>3</b></span><strong>REPAIR ORDER <b>D·01 → D·02 → D·03</b></strong></div></aside><span className="revision-tab">REVISION 04 → 05</span></section> }
function Landing() { return <div className="landing-reference"><header className="landing-reference-header"><Link className="wordmark" to="/"><span><strong>GROUND<br /><span className="shift">SHIFT</span></strong><small>DEPENDENCY ANALYSIS INSTRUMENT</small></span></Link><span className="landing-reference-network">STUDIO-DEV</span></header><main className="landing-reference-main"><section className="landing-field"><div className="landing-field-bands" aria-hidden="true"><span /><span /><span /><span /></div><div className="landing-reference-copy"><span className="eyebrow light-eyebrow">DEPENDENCY INFRASTRUCTURE</span><h1>WHEN THE BASIS MOVES,<br />YOU SEE WHAT BREAKS.</h1><p>Track dependency drift, identify stale decisions, and repair them in the order the graph actually requires.</p><div className="feature-strips"><div className="feature-strip"><span>01</span><strong>FAULT PROPAGATION</strong></div><div className="feature-strip"><span>02</span><strong>REVISION BASIS</strong></div><div className="feature-strip"><span>03</span><strong>BLAST RADIUS</strong></div><div className="feature-strip"><span>04</span><strong>ORDERED REPAIR</strong></div></div><Link className="reference-cta" to="/app">OPEN LIVE MAP <ArrowRight size={15} /></Link></div></section><LandingStrataDemo /></main></div> }
